// UpstreamRequestLogCreateBulk is the builder for creating many UpstreamRequestLog entities in bulk.
type UpstreamRequestLogCreateBulk struct {
	config
	err      error
	builders []*UpstreamRequestLogCreate
	conflict []sql.ConflictOption
}

// Save creates the UpstreamRequestLog entities in the database.
func (urlcb *UpstreamRequestLogCreateBulk) Save(ctx context.Context) ([]*UpstreamRequestLog, error) {
	if urlcb.err != nil {
		return nil, urlcb.err
	}
	specs := make([]*sqlgraph.CreateSpec, len(urlcb.builders))
	nodes := make([]*UpstreamRequestLog, len(urlcb.builders))
	mutators := make([]Mutator, len(urlcb.builders))
	for i := range urlcb.builders {
		func(i int, root context.Context) {
			builder := urlcb.builders[i]
			builder.defaults()
			var mut Mutator = MutateFunc(func(ctx context.Context, m Mutation) (Value, error) {
				mutation, ok := m.(*UpstreamRequestLogMutation)
				if !ok {
					return nil, fmt.Errorf("unexpected mutation type %T", m)
				}
				if err := builder.check(); err != nil {
					return nil, err
				}
				builder.mutation = mutation
				var err error
				nodes[i], specs[i] = builder.createSpec()
				if i < len(mutators)-1 {
					_, err = mutators[i+1].Mutate(root, urlcb.builders[i+1].mutation)
				} else {
					spec := &sqlgraph.BatchCreateSpec{Nodes: specs}
					spec.OnConflict = urlcb.conflict
					// Invoke the actual operation on the latest mutation in the chain.
					if err = sqlgraph.BatchCreate(ctx, urlcb.driver, spec); err != nil {
						if sqlgraph.IsConstraintError(err) {
							err = &ConstraintError{msg: err.Error(), wrap: err}
						}
					}
				}
				if err != nil {
					return nil, err
				}
				mutation.id = &nodes[i].ID
				if specs[i].ID.Value != nil {
					id := specs[i].ID.Value.(int64)
					nodes[i].ID = int(id)
				}
				mutation.done = true
				return nodes[i], nil
			})
			for i := len(builder.hooks) - 1; i >= 0; i-- {
				mut = builder.hooks[i](mut)
			}
			mutators[i] = mut
		}(i, ctx)
	}
	if len(mutators) > 0 {
		if _, err := mutators[0].Mutate(ctx, urlcb.builders[0].mutation); err != nil {
			return nil, err
		}
	}
	return nodes, nil
}

